// สร้างข้อความไทยจาก event ที่ backend ส่งมา (ticket.created / ticket.status_changed / ...)
const body = $input.first().json.body || $input.first().json;
const ev = body.event || "unknown";
const LABEL = {
  new: "🆕 รอรับเรื่อง", assigned: "👷 มอบหมายแล้ว", in_progress: "🔧 กำลังดำเนินการ",
  pending: "⏳ รออะไหล่/รอภายนอก", waiting_parts: "⏳ รออะไหล่", waiting_user: "⏳ รอผู้ใช้ตอบกลับ",
  resolved: "✅ ซ่อมเสร็จ รอยืนยัน", closed: "🔒 ปิดงานแล้ว", cancelled: "❌ ยกเลิก",
};
const who = {
  qr: "สแกน QR", public: "ฟอร์มแจ้งซ่อม", web: "เว็บ", line: "LINE", pm: "บำรุงรักษา",
};
let msg = "";
if (ev === "ticket.created") {
  msg = ["🆕 Ticket ใหม่: " + (body.ticket_id || "-"),
         "เรื่อง: " + (body.title || "-"),
         "อุปกรณ์: " + (body.device_id || "-"),
         "ผู้แจ้ง: " + (body.reporter_name || "-") + (body.reporter_phone ? " (" + body.reporter_phone + ")" : ""),
         "ช่องทาง: " + (who[body.channel] || body.channel || "-"),
         "ความเร่งด่วน: " + (body.priority || "normal")].join("\n");
} else if (ev === "ticket.status_changed") {
  msg = ["🔔 เปลี่ยนสถานะ " + (body.ticket_id || "-"),
         "จาก: " + (LABEL[body.from_status] || body.from_status || "-") + " → " + (LABEL[body.to_status] || body.to_status || "-"),
         "เรื่อง: " + (body.title || "-"),
         "ผู้รับผิดชอบ: " + (body.assigned_to || "-")].join("\n");
} else {
  msg = "📣 " + ev + "\n" + JSON.stringify(body).slice(0, 500);
}
return [{ json: { to: $env.LINE_GROUP_ID, text: msg } }];
